/**
 * MobiKwik gateway adapter — ported from the EdgePay gateway suite
 * GENERATED by scripts/port-gateways/generate.py — regenerate, do not hand-edit.
 * Flow: form-raw.
 * PORT-NOTE: sandbox "simulation" fallback (SIM_/uniqid fake success) stripped — API failure now throws.
 */
import { escapeHtml } from '../kit/form';

import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';

const SANDBOX_URL = "https://zaakstaging.zaakpay.com/api/paymentTransact/v8";
const LIVE_URL = "https://api.zaakpay.com/api/paymentTransact/v8";


export class MobikwikGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "MobiKwik",
      slug: "mobikwik",
      version: '1.0.0',
      description: "MobiKwik Zaakpay hosted checkout integration",
      author: 'EdgePay Gateway Suite (AGPLv3)',
      type: 'gateway',
      supported_currencies: ["INR"],
      capabilities: ["verification"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "merchant_id", label: "Merchant Identifier (MID)", type: "text" as const, required: true },
      { name: "secret_key", label: "Secret Key", type: "password" as const, required: true },
    ];
  }

  async initiate(_params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const mode = String(credentials.mode ?? 'sandbox');
    const checkoutUrl = (String(mode) === String("live")) ? (LIVE_URL) : (SANDBOX_URL);
    const formHtml = `<form id="mobikwik_checkout_form" method="post" action="${String(escapeHtml(String(checkoutUrl)))}">`;
    return { form_html: formHtml };
  }

  async verify(callbackData: Record<string, unknown>, _credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["responseCode"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    // PORT-NOTE: upstream verifies via the callback payload only (no
    // server-side API); the unguessable checkout callback token is the
    // authenticity gate for this flow.
    const ok = String(cb["responseCode"]) === String("100");
    return {
          success: ok,
          gateway_trx_id: String(""),
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
      amount: null,
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    return false;
  }
}
